package justfatlard.village_quests.manager;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;
import justfatlard.village_quests.data.Dialogue;
import justfatlard.village_quests.quest.VillagerMemory;
import net.minecraft.server.level.ServerPlayer;

/**
 * The lines a villager opens with that no writer sat down and authored as a
 * scene: the reaction they have been holding since you fixed the door, the
 * accusation after a theft, the callback to last week's conversation, the
 * remark about your glowing skin. They are generated by a dozen systems, and
 * for a long time they were glued in front of whatever greeting came up next,
 * so a villager could open with an accusation, a weather complaint and a
 * question about bees in one breath, and the buttons answered only the bees.
 *
 * <p>Here each of those lines gets what the registry already gives authored
 * ones: a node whose replies answer it, closes in the villager's voice, and a
 * walk-away that fits. The manager picks exactly one opening per conversation
 * (see {@code DialogueManager.chooseOpening}); this class is what it picks from.
 *
 * <p>Two shapes. An <b>exchange</b> is a node with two or three player moves,
 * each landing on a close. The <b>floor</b> is a line and a walk-away, which
 * the writing guide says is a complete conversation too. Reputation lands on
 * closes and only for trust events: owning what you did, to someone's face,
 * pays a little and quiets the rest of the village; denying it costs.
 */
final class Openings {
   private Openings() {
   }

   /** One opening: the text on screen, the node whose replies answer it, and how it was chosen. */
   record Opening(String text, Dialogue node, ConversationMemory.ConversationTopic topic, boolean bare, String walkAway) {
      /** A registered greeting, with its own authored replies and walk-away. */
      static Opening greeting(Dialogue greeting, String text, ConversationMemory.ConversationTopic topic) {
         return new Opening(text, greeting, topic, false, null);
      }

      /** A registered greeting about something that happened; nothing is said in front of it. */
      static Opening event(Dialogue greeting, String text) {
         return new Opening(text, greeting, null, true, null);
      }
   }

   /**
    * The generated openers, by what kind of thing was said. {@code bare} means
    * no manner beat in front of it: nobody yawns before telling you they know
    * what you stole. {@code topic} is what the conversation is recorded as.
    */
   enum Kind {
      HELD("held", true, null, "Right.", "*nod*", "I'll leave you to it."),
      AFTERMATH("aftermath", true, ConversationMemory.ConversationTopic.DEEP_MOMENT, "Take care.", "Well.", "*nod*"),
      REFUSAL_REMEMBERED("refused", true, ConversationMemory.ConversationTopic.DEEP_MOMENT, "It's alright.", "Leave it there."),
      GUARDED("guarded", true, null, "Alright.", "Another time."),
      GRIEF("grief", true, null, "*say nothing*", "*stay a moment*", "I'm sorry."),
      WONDER("wonder", false, null, "Ha.", "*shake head*", "Don't look at me."),
      CALLBACK_QUEST("cb_quest", false, null, "Anyway."),
      CALLBACK_LORE("cb_lore", false, null, "Let's not get into it here."),
      CALLBACK_GOSSIP("cb_gossip", false, null, "Say no more."),
      CALLBACK("cb", false, null, "Ha. Yeah.", "True enough.", "Anyway."),
      GOSSIP_ASK("gossip", false, ConversationMemory.ConversationTopic.GOSSIP, "I'll keep an eye out.", "Not my business."),
      PRAISE("praise", false, null, "Ha.", "Don't start."),
      ODDITY("oddity", false, null, "Don't ask.", "Later."),
      OBSERVATION("observation", false, null, "Noted.", "I'll have a look."),
      FIXED("fixed", false, null, "Ha.", "Somebody did."),
      LORE("lore", false, ConversationMemory.ConversationTopic.LORE_SHARED, "Huh.", "I'll think on that.", "*nod slowly*"),
      HOUR("hour", false, null, "Goodnight.", "Get some sleep.", "Same to you."),
      WEATHER("weather", false, ConversationMemory.ConversationTopic.WEATHER, "Stay dry.", "It'll pass.", "*look at the sky*"),
      CONFIDENCE("confidence", true, null, "Your secret.", "I won't tell.", "*nod*"),
      PRESENCE("presence", true, null, "Guess so.", "Getting there.", "Feels like it."),
      RECOGNITION("recognition", true, null, "Here I am.", "Couldn't stay away.", "*nod*"),
      AFFINITY("affinity", false, null, "I'll keep an eye out.", "Noted.", "Ha. Maybe."),
      CLUE("clue", true, null, "That helps.", "I'll follow that up.", "Thanks."),
      REFERRAL("referral", true, null, "Another time, then.", "Not right now."),
      CRAFT("craft", true, null, "Alright.", "*nod*"),
      NITWIT("nitwit", false, null, "Right.", "Sure.", "*nod slowly*"),
      SECRET("secret", true, null, "I'd rather stay out of it.", "Ask someone else.");

      final String id;
      final boolean bare;
      final ConversationMemory.ConversationTopic topic;
      final String[] walkAways;

      Kind(String id, boolean bare, ConversationMemory.ConversationTopic topic, String... walkAways) {
         this.id = "open_" + id;
         this.bare = bare;
         this.topic = topic;
         this.walkAways = walkAways;
      }
   }

   private record Reply(String label, String close, int arrival, String walkAway) {
   }

   private static Map<String, Dialogue> registry;
   private static final Map<RecentActionsMemory.ActionType, String> ACTION_NODES = new HashMap<>();
   private static final Map<RecentActionsMemory.ActionType, String[]> ACTION_WALK_AWAYS = new HashMap<>();
   /**
    * Closes that settle the matter: the owning reply to a wrong, any reply to a
    * good turn. Arriving there stops the rest of the village raising it.
    */
   private static final Map<String, RecentActionsMemory.ActionType> SETTLED_AT = new HashMap<>();

   static Opening of(Kind kind, String text) {
      return new Opening(text, registry.get(kind.id), kind.topic, kind.bare, pick(kind.walkAways));
   }

   /**
    * The opener for something the player just did, or null when the village
    * has no line for it. A wrong is raised at every door until it is owned;
    * a good turn is mentioned by some, because a village where everyone stops
    * you to say thanks is a village performing for you.
    */
   static Opening ofAction(RecentActionsMemory.PlayerAction action, ThreadLocalRandom rng) {
      String text = RecentActionsMemory.openingFor(action);
      String nodeId = ACTION_NODES.get(action.type);
      if (text == null || nodeId == null) {
         return null;
      }

      if (action.type.getToneModifier() >= 0.0F && rng.nextDouble() >= 0.35) {
         return null;
      }

      return new Opening(text, registry.get(nodeId), null, true, pick(ACTION_WALK_AWAYS.get(action.type)));
   }

   /**
    * A line a villager says because of what they remember, sorted by what
    * remembering it feels like. Grief and guardedness are the villager's
    * present state and always speak; a settled gratitude comes up now and
    * then, since a villager who thanks you for the house every single morning
    * has stopped sounding like a person and started sounding written.
    */
   static Opening ofMemory(VillagerMemory.Remembered remembered, ThreadLocalRandom rng) {
      Kind kind = kindOf(remembered.type());
      boolean present = kind == Kind.GRIEF || kind == Kind.GUARDED;
      if (!present && rng.nextDouble() >= 0.3) {
         return null;
      }

      return of(kind, remembered.text());
   }

   private static Kind kindOf(VillagerMemory.MemoryType type) {
      if (type == null) {
         return Kind.AFTERMATH;
      }

      return switch (type) {
         case SAW_RAINBOW_SHEEP, SKY_BOOM, SQUID_SURVIVOR -> Kind.WONDER;
         case VULNERABILITY_HANGOVER, SECRET_REVEALED, TRUST_BETRAYED -> Kind.GUARDED;
         case GOLEM_LOST, HOME_DESTROYED, FRIEND_TRANSFORMED -> Kind.GRIEF;
         case VIOLENCE_REFUSED, SABOTAGE_REFUSED, THEFT_REFUSED -> Kind.REFUSAL_REMEMBERED;
         default -> Kind.AFTERMATH;
      };
   }

   static Opening ofCallback(ConversationMemory.Callback callback) {
      Kind kind = switch (callback.topic()) {
         case QUEST_GIVEN -> Kind.CALLBACK_QUEST;
         case LORE_SHARED -> Kind.CALLBACK_LORE;
         case GOSSIP -> Kind.CALLBACK_GOSSIP;
         default -> Kind.CALLBACK;
      };
      return of(kind, callback.text());
   }

   /** Called when a conversation reaches a node; a settling close quiets the rest of the village. */
   static void onArrival(ServerPlayer player, String nodeId) {
      RecentActionsMemory.ActionType settled = SETTLED_AT.get(nodeId);
      if (settled != null) {
         RecentActionsMemory.markAddressed(player, settled);
      }

      // "I'll put it back" is a promise the chest watch can see kept.
      if (settled == RecentActionsMemory.ActionType.THEFT) {
         RecentActionsMemory.promiseReturn(player);
      }
   }

   private static String pick(String[] pool) {
      return pool[ThreadLocalRandom.current().nextInt(pool.length)];
   }

   static void registerAll(Map<String, Dialogue> target) {
      registry = target;

      for (Kind kind : Kind.values()) {
         floor(kind);
      }

      // HELD stays a floor. What a villager holds is whatever a system queued:
      // thanks for a door, a rebuke after a refusal, a teacher's next line. No
      // reply fits all of those, so the villager says it and the player leaves.

      // Gratitude that has had time to settle. "The house still stands."
      exchange(Kind.AFTERMATH,
         new Reply("It was nothing.", "It wasn't. Let me have this one.", 0, "*nod*"),
         new Reply("How are things now?", "Better. Not the same. Better.", 0, "Good."),
         new Reply("*say nothing*", "You're not one for speeches. Good. Neither am I.", 0, "Well.")
      );

      // "I asked you to do something wrong. And you said no."
      exchange(Kind.REFUSAL_REMEMBERED,
         new Reply("You'd have regretted it.", "I'd have regretted it. I regret asking. That's smaller. I can carry that.", 0, "It's alright."),
         new Reply("*say nothing*", "Thank you for not making me say more.", 0, "*nod*")
      );

      // "How'd that go? The thing I asked about."
      exchange(Kind.CALLBACK_QUEST,
         new Reply("Done, actually.", "Then I'm glad I asked you and not the fletcher. Don't tell him I said that.", 0, "Ha. I won't."),
         new Reply("Still working on it.", "No hurry. Well. Some hurry. It'll keep.", 0, "It will."),
         new Reply("It didn't work out.", "Some don't. Thanks for saying so instead of walking the long way round my door.", 0, "Fair.")
      );

      // "You didn't tell anyone what I said, did you?"
      exchange(Kind.CALLBACK_LORE,
         new Reply("I haven't told anyone.", "Good. Keep not telling. It sounds mad said out loud.", 0, "It's between us."),
         new Reply("I've been thinking about it too.", "Don't. That's my advice. I ignore it daily.", 0, "Ha. Noted.")
      );

      // "Don't repeat what I told you."
      exchange(Kind.CALLBACK_GOSSIP,
         new Reply("I won't repeat it.", "Good. This village has one secret, and it's that nobody keeps any.", 0, "Ha."),
         new Reply("Was it true, though?", "*looks away* True enough that I shouldn't have said it.", 0, "Say no more.")
      );

      // "Have you noticed Rowena looks tired lately?"
      exchange(Kind.GOSSIP_ASK,
         new Reply("Now that you mention it.", "Right? Somebody should ask them. Not me. I'm bad at it.", 0, "I'll keep an eye out."),
         new Reply("Can't say I have.", "Maybe it's only me, then. I notice things and then I can't stop.", 0, "Anyway.")
      );

      // "Tomas hasn't stopped talking about you."
      exchange(Kind.PRAISE,
         new Reply("They exaggerate.", "They do. Not about this, I think.", 0, "Anyway."),
         new Reply("I just did what needed doing.", "That's exactly what they said you'd say.", 0, "Ha.")
      );

      // "You're glowing. You DO know that, right?"
      exchange(Kind.ODDITY,
         new Reply("Long story.", "Keep it. I've got enough stories.", 0, "Anyway."),
         new Reply("You get used to it.", "I won't. And I'd rather not learn how you did.", 0, "Fair.")
      );

      // "The fence by the east field has a gap in it."
      exchange(Kind.OBSERVATION,
         new Reply("I'll take a look.", "Would you? I keep meaning to, and then it's dark.", 0, "Consider it looked at."),
         new Reply("Whose job is that?", "Everyone's. Which is how it stays nobody's.", 0, "Noted.")
      );

      // "Someone fixed the fence. Was that you?"
      exchange(Kind.FIXED,
         new Reply("It needed doing.", "It did. Somebody had to notice it, then somebody had to do it. Both rarer than you'd think.", 0, "*nod*"),
         new Reply("Wasn't me.", "Then somebody. Good for somebody.", 0, "Ha.")
      );

      // What you did in the last few minutes, and the village saw. The owned
      // reply is always first; arriving at its close marks the action addressed.
      action(RecentActionsMemory.ActionType.VILLAGER_HARMED, new String[]{"*go*", "*walk off*"},
         new Reply("I was wrong. I know it.", "*doesn't come closer* Knowing is a start. They're the one who needs to hear it, not me.", 1, "I'll go to them."),
         new Reply("They came at me first.", "*turns away* That's not what anyone saw.", -2, "Believe what you like."),
         new Reply("*say nothing*", "Go on, then. Nothing to say to me either.", 0, "*go*")
      );
      action(RecentActionsMemory.ActionType.THEFT, new String[]{"*go*", "*turn and go*"},
         new Reply("I'll put it back.", "Then put it back. What I know can change after that. Not before.", 1, "Fair."),
         new Reply("I didn't take anything.", "*looks at your hands, then at your face* Alright.", -2, "Think what you want."),
         new Reply("It was just sitting there.", "So is my door, at night. I still expect it shut come morning.", -1, "Point taken.")
      );
      action(RecentActionsMemory.ActionType.DESTROYED_PROPERTY, new String[]{"*go*", "Alright."},
         new Reply("I'll put it right.", "See that you do. The wood's the small part. The big part is you thought nobody would mind.", 1, "Understood."),
         new Reply("It was in the way.", "So am I, most days. Nobody's put a pick through me yet.", -1, "Alright."),
         new Reply("*say nothing*", "*goes back to work*", 0, "*go*")
      );
      action(RecentActionsMemory.ActionType.QUEST_ABANDONED, new String[]{"Fair.", "Maybe so."},
         new Reply("I'll go and explain.", "Explain. Don't excuse. They know the difference, they've had practice.", 1, "I'm going."),
         new Reply("Things came up.", "They do. Say so before, next time. After is just news.", 0, "Fair."),
         new Reply("It wasn't worth doing.", "It was worth asking for. That's what you left them holding.", -1, "Maybe so.")
      );
      action(RecentActionsMemory.ActionType.KILLED_IRON_GOLEM, new String[]{"*go*", "*turn away*"},
         new Reply("I know what I did.", "Then you know what it was to us. Three winters at that gate. It never once asked for anything.", 1, "I know."),
         new Reply("It came at me.", "It comes at what hits us. Sit with that.", -2, "*turn away*"),
         new Reply("*say nothing*", "*turns back to the work*", 0, "*go*")
      );

      action(RecentActionsMemory.ActionType.VILLAGER_SAVED, new String[]{"Well.", "Good."},
         new Reply("Anyone would have.", "No. That's the thing. Not anyone.", 0, "Well."),
         new Reply("Are they alright?", "Shaken. By the fire, telling it bigger every hour. They'll be fine.", 0, "Good.")
      );
      action(RecentActionsMemory.ActionType.DEFENDED_VILLAGE, new String[]{"Glad of it.", "Ha. Alright."},
         new Reply("Long night.", "For you. We slept. First night in a week I didn't lie there counting groans.", 0, "Glad of it."),
         new Reply("They'll be back.", "They always are. So are you, lately. I'll take those odds.", 0, "Ha. Alright.")
      );
      action(RecentActionsMemory.ActionType.HELPED_BUILD, new String[]{"*nod*", "Guess so."},
         new Reply("Mine.", "Thought so. Nobody here squares a corner like that.", 0, "*nod*"),
         new Reply("Took a few tries.", "It doesn't show. That's the whole trick.", 0, "Guess so.")
      );
      action(RecentActionsMemory.ActionType.KILLED_ZOMBIE, new String[]{"Sleep well.", "Goodnight."},
         new Reply("One or two.", "One or two is one or two fewer at my door. I count.", 0, "Sleep well."),
         new Reply("Couldn't sleep anyway.", "Neither could they, I suppose.", 0, "Ha. Goodnight.")
      );
      action(RecentActionsMemory.ActionType.SURVIVED_NIGHT, new String[]{"*nod*", "Maybe."},
         new Reply("Wasn't planning to leave.", "Good. The ones who plan to stay are the ones who do.", 0, "*nod*"),
         new Reply("Nowhere else to be.", "That's how most of us started. Then one day it was here.", 0, "Maybe.")
      );
      action(RecentActionsMemory.ActionType.QUEST_COMPLETED, new String[]{"Well.", "Ha. Alright."},
         new Reply("They asked.", "Plenty get asked. Fewer turn up.", 0, "Well."),
         new Reply("It wasn't much.", "They'll tell it like it was plenty. Let them.", 0, "Ha. Alright.")
      );
      action(RecentActionsMemory.ActionType.RETURNED_GOODS, new String[]{"Well.", "*nod*"},
         new Reply("Said I would.", "People say. Fewer do. I'll remember which you were.", 0, "Well."),
         new Reply("*say nothing*", "*nods again* Good. Then neither will I.", 0, "*nod*")
      );
      action(RecentActionsMemory.ActionType.DIED_AND_RETURNED, new String[]{"Anyway.", "Later."},
         new Reply("I'm fine.", "You said that like you were checking. Alright.", 0, "Anyway."),
         new Reply("Don't ask.", "Wasn't going to. Sit down before you fall down, though.", 0, "Later.")
      );
   }

   /**
    * A kind's node with no replies of its own: the line, then the walk-away.
    * The registered label is only there for the startup validator; the manager
    * draws the shown label from the kind's pool.
    */
   private static void floor(Kind kind) {
      registry.put(kind.id, new Dialogue(kind.id, "", -999, 999, Dialogue.DialogueType.IDLE_CHAT).walkAway(kind.walkAways[0]));
   }

   /** Replaces a kind's floor node with one whose replies each land on a close. */
   private static void exchange(Kind kind, Reply... replies) {
      registry.put(kind.id, node(kind.id, replies));
   }

   /**
    * The exchange for something the player just did. When it was a wrong, the
    * first reply is the owning one and only its close settles it; when it was
    * a good turn, answering anyone settles it.
    */
   private static void action(RecentActionsMemory.ActionType type, String[] walkAways, Reply... replies) {
      String id = "open_did_" + type.name().toLowerCase();
      registry.put(id, node(id, replies));
      ACTION_NODES.put(type, id);
      ACTION_WALK_AWAYS.put(type, walkAways);
      if (type.getToneModifier() < 0.0F) {
         SETTLED_AT.put(id + "_0", type);
      } else {
         for (int i = 0; i < replies.length; i++) {
            SETTLED_AT.put(id + "_" + i, type);
         }
      }
   }

   private static Dialogue node(String id, Reply... replies) {
      Dialogue opener = new Dialogue(id, "", -999, 999, Dialogue.DialogueType.IDLE_CHAT);

      for (int i = 0; i < replies.length; i++) {
         Reply reply = replies[i];
         String closeId = id + "_" + i;
         opener.addResponse(new Dialogue.DialogueResponse(reply.label(), 0, closeId, false, null));
         registry.put(closeId, new Dialogue(closeId, reply.close(), -999, 999, Dialogue.DialogueType.IDLE_CHAT).arrival(reply.arrival()).walkAway(reply.walkAway()));
      }

      return opener;
   }
}
